#include "NativeChatModule.h"

#ifdef __ANDROID__
// Generated by `go build -buildmode=c-shared` for each Android ABI.
// The header already wraps its declarations in `extern "C"`.
// iOS needs the equivalent library wired up in the Podfile/Xcode first.
#include "libchat.h"
#endif

namespace facebook::react {

NativeChatModule::NativeChatModule(std::shared_ptr<CallInvoker> jsInvoker)
    : NativeChatModuleCxxSpec(std::move(jsInvoker)) {}

std::string NativeChatModule::reverseString(jsi::Runtime &rt,
                                            std::string input) {
#ifdef __ANDROID__
  char *reversed = ChatReverse(const_cast<char *>(input.c_str()));
  if (reversed == nullptr) {
    return {};
  }

  std::string result(reversed);
  ChatFree(reversed);
  return result;
#else
  std::reverse(input.begin(), input.end());
  return input;
#endif
}

} // namespace facebook::react
